      if(src&&mainImg){mainImg.style.opacity='0';mainImg.style.transition='opacity .2s ease';setTimeout(function(){mainImg.src=src;mainImg.style.opacity='1';},180);}
      thumbs.forEach(function(t){t.classList.remove('a50-hero__thumb--active');});
      thumb.classList.add('a50-hero__thumb--active');
    });
  });
})();
</script></div></div></div></div></div></div></div></section></div>
